file.content:
    return json.dumps(value, ensure_ascii=False)


# Sentinels tagging container and ambiguous-scalar kinds inside value keys.
# They are plain objects, so they can never equal a string, number, or other
# payload value; identity and hash are stable within the process, which is
# all a per-call engine registry needs.
_VKEY_BOOL = object()
_VKEY_FLOAT = object()
_VKEY_LIST = object()
_VKEY_TUPLE = object()
_VKEY_DICT = object()
_VKEY_OTHER = object()


def _vtype_key(value: Any) -> Any:
    """Type-faithful, sortable identity of a dict key (or other hashable).

    Every identity is a tag-first tuple, so identities of differently typed
    keys always order and compare without ``TypeError`` — an integer fact
    key never merges with or mis-sorts against the string with the same
    digits, and a tuple key never merges with anything else.  Used only for
    dict keys, which need a deterministic order; values use
    :func:`_vvalue_key`.
    """
    if isinstance(value, str):
        return ("s", value)
    if isinstance(value, bool):
        return ("b", value)
    if isinstance(value, int):
        return ("i", value)
    if isinstance(value, float):
        return ("f", value)
    if value is None:
        return ("n",)
    if isinstance(value, tuple):
        return ("t", tuple(_vtype_key(item) for item in value))
    return ("o", type(value).__qualname__, repr(value))


def _vvalue_key(value: Any) -> Any:
    """Type-faithful structural identity of a leaf credential value.

    The reuse registry must never merge values whose compact JSON text
    merely *looks* equal while their Python types differ: an integer fact
    or condition key and the string with the same digits, a tuple and the
    list with the same items, ``True`` and ``1``.  This key walks the
    value once and records the real type of every container and key, so
    only values equal in both type and value share an identity; anything
    else falls through to full validation, which rejects it.  Strings and
    ints map to themselves (they cannot collide with any other type's
    identity); containers, bools, floats, and exotica are tagged with
    sentinels that no payload value can equal.  Dict item order is
    normalized away by sorting on the (type-tagged) keys, and every legal
    credential contains only dicts, lists, strings, bools, ints, and
    nulls, for which the key is exact.  This is a structural walk, not a
    serialization: no text or byte form of the value is produced for
    keying.
    """
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        items = [
            (_vtype_key(key), _vvalue_key(item)) for key, item in value.items()
        ]
        items.sort()
        return (_VKEY_DICT, tuple(items))
    if isinstance(value, list):
        return (_VKEY_LIST, tuple(_vvalue_key(item) for item in value))
    if isinstance(value, tuple):
        return (_VKEY_TUPLE, tuple(_vvalue_key(item) for item in value))
    if isinstance(value, bool):
        return (_VKEY_BOOL, value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return (_VKEY_FLOAT, value)
    if value is None:
        return None
    return (_VKEY_OTHER, type(value).__qualname__, repr(value))


class _CanonicalDict(dict):
    """A plain dict carrying the root of a canonical generator result.

    It behaves exactly like a plain ``dict`` in every respect — it *is* one:
    equality, ordering, iteration, JSON encoding, and ``isinstance`` checks
    are unchanged.  The only addition is a ``__deepcopy__`` that rebuilds
    the independent copy through the canonical compact JSON form, which is
    far cheaper than the generic recursive copier for the very large
    credential trees these functions return.  The copy is made of plain
    dicts and lists, so nothing beyond copying speed is observable, and the
    copy remains fully independent of the original at every level.
    """

    def __deepcopy__(self, memo: dict) -> Any:
        clone = json.loads(
            json.dumps(self, ensure_ascii=False, separators=(",", ":"))
        )
        memo[id(self)] = clone
        return clone


def _emit(canonical_json: str) -> dict[str, Any]:
    """Materialize a canonical JSON document as an independent result tree."""
    return _CanonicalDict(json.loads(canonical_json))


def _v_member_payload(singular: str, item_id: str, child_json: str) -> str:
    return '{"id":' + _vjs(item_id) + ',"' + singular + '":' + child_json + "}"


class _VKey:
    """A hash-consed composite value key.

    Composite nodes (bundles, diffs, proofs) key their registries by tuples
    of scalar fields plus their children's keys.  Plain tuples re-hash the
    whole nested structure on every lookup; wrapping the tuple caches the
    hash once, so a repeat occurrence resolves in O(1).  Equality still
    compares the full underlying tuple, so distinct values can never merge.
    """

    __slots__ = ("parts", "_hash")

    def __init__(self, parts: Any) -> None:
        self.parts = parts
        self._hash = hash(parts)

    def __hash__(self) -> int:
        return self._hash

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, _VKey):
            return NotImplemented
        return self.parts == other.parts


class _VNode:
    __slots__ = (
        "key", "canonical", "json", "sem", "semkey", "dsem", "dsemkey",
        "truth", "complete",
        "root", "root_after", "members", "before_node", "after_node",
        "digest", "stage_parts",
    )

    def __init__(self) -> None:
        self.key: Any = None
        self.canonical: Any = None
        self.json: str = ""
        self.sem: Any = None
        self.semkey: Any = None
        self.dsem: Any = None
        self.dsemkey: Any = None
        self.truth: bool = False
        self.complete: bool = True
        self.root: str = ""
        self.root_after: str = ""
        self.members: list[Any] = []
        self.before_node: Any = None
        self.after_node: Any = None
        self.digest: str = ""
        self.stage_parts: list[str] = []


class _VEngine:
    def __init__(self) -> None:
        self.cred: dict[str, _VNode] = {}
        self.mbundle: dict[Any, _VNode] = {}
        self.mdiff: dict[Any, _VNode] = {}
        self.p0: dict[Any, _VNode] = {}
        self.b0: dict[Any, _VNode] = {}
        self.d0: dict[Any, _VNode] = {}
        self.p1: dict[Any, _VNode] = {}
        self.b1: dict[Any, _VNode] = {}
        self.d1: dict[Any, _VNode] = {}
        self.p2: dict[Any, _VNode] = {}
        self.b2: dict[Any, _VNode] = {}
        self.d2: dict[Any, _VNode] = {}

    # ------------------------------------------------------------ leaf cred
    def credential(self, value: Any, field: str) -> _VNode:
        if not isinstance(value, dict):
            raise ValueError(f"{field} must be a credential dict")
        # The reuse identity is a type-faithful structural key, not JSON
        # text: it records the real type of every container and key, so a
        # value that merely serializes like an already-seen credential (an
        # integer fact or condition key where the same digits were verified
        # as a string, a tuple where a list is required) never reuses that
        # credential's verified node.  Such a value falls through to full
        # validation, which reports the structural/type violation as
        # ValueError (never a TypeError), so it is never cached; only a
        # genuine type-and-value match resolves to the cached node.
        key = _VKey(("cred", _vvalue_key(value)))
        node = self.cred.get(key)
        if node is not None:
            return node
        content, declared, recomputed, chain_ok, chain_root = (
            _check_verified_matrix_attestation(value, field)
        )
        canonical = copy.deepcopy(content)
        canonical["digest"] = declared
        cjson = json.dumps(canonical, ensure_ascii=False, separators=(",", ":"))
        node = _VNode()
        node.key = key
        node.canonical = canonical
        node.json = cjson
        node.sem = _matrix_credential_semantics(content)
        node.semkey = (
            "cred",
            json.dumps(node.sem, ensure_ascii=False, sort_keys=True,
                       separators=(",", ":")),
        )
        node.truth = bool(
            chain_ok
            and content["policy"]["root"] == chain_root
            and declared == recomputed
        )
        self.cred[key] = node
        return node

    # ------------------------------------------------------- shared members
    def _bundle_members(self, value, field, plural, singular, parse_child):
        if not isinstance(value, dict) or set(value) != {"root", plural}:
            raise ValueError(
                f"{field} must be a dict with exactly the keys root, {plural}"
            )
        root = _check_hex64(value["root"], f"{field}.root")
        raw = value[plural]
        if not isinstance(raw, list) or not raw:
            raise ValueError(f"{field}.{plural} must be a non-empty list")
        members: list[tuple[str, _VNode, str, str]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, member in enumerate(raw):
            mf = f"{field}.{plural}[{index}]"
            if not isinstance(member, dict) or set(member) != {
                "id", singular, "previous", "digest"
            }:
                raise ValueError(
                    f"{mf} must be a dict with exactly the keys "
                    f"id, {singular}, previous, digest"
                )
            item_id = _check_non_empty_str(member["id"], f"{mf}.id")
            if item_id in seen:
                raise ValueError(
                    f"{field}.{plural} contains a duplicate id: {item_id!r}"
                )
            if previous_id is not None and item_id <= previous_id:
                raise ValueError(
                    f"{field}.{plural} must be ordered by id in ascending "
                    "Unicode code point order"
                )
            child = parse_child(member[singular], f"{mf}.{singular}")
            prev = _check_hex64(member["previous"], f"{mf}.previous")
            dig = _check_hex64(member["digest"], f"{mf}.digest")
            members.append((item_id, child, prev, dig))
            seen.add(item_id)
            previous_id = item_id
        return root, members

    def _assemble_bundle(self, tag, registry, key, root, members, plural, genesis):
        singular = "proof" if plural == "proofs" else "report"
        label = b',"proof":' if plural == "proofs" else b',"report":'
        truth = True
        running = genesis
        parts: list[str] = []
        for item_id, child, prev, dig in members:
            # Hash the member payload incrementally from the cached child
            # bytes instead of concatenating a throwaway payload string.
            hasher = hashlib.sha256(running.encode("ascii"))
            hasher.update(b'{"id":')
            hasher.update(_vjs(item_id).encode("utf-8"))
            hasher.update(label)
            hasher.update(child.json.encode("utf-8"))
            hasher.update(b"}")
            recomputed = hasher.hexdigest()
            parts.append(
                '{"id":' + _vjs(item_id)
                + ',"' + singular + '":'
                + child.json
                + ',"previous":' + _vjs(prev)
                + ',"digest":' + _vjs(dig) + "}"
            )
            if not child.truth or prev != running or dig != recomputed:
                truth = False
            running = recomputed
        if root != running:
            truth = False
        node = _VNode()
        node.key = key
        node.root = root
        node.members = members
        node.truth = truth
        node.sem = [(i, n.sem) for i, n, _p, _d in members]
        node.semkey = (
            tag,
            tuple((i, n.semkey) for i, n, _p, _d in members),
        )
        node.json = (
            '{"root":' + _vjs(root) + ',"' + plural + '":['
            + ",".join(parts) + "]}"
        )
        node.canonical = None
        registry[key] = node
        return node

    # ------------------------------------------------------------ mbundle
    def matrix_bundle(self, value: Any, field: str) -> _VNode:
        root, members = self._bundle_members(
            value, field, "reports", "report",
            lambda v, f: self.credential(v, f),
        )
        key = _VKey(
            ("mbundle", root, tuple((i, n.key, p, d) for i, n, p, d in members))
        )
        node = self.mbundle.get(key)
        if node is not None:
            return node
        return self._assemble_bundle(
            "mbundle", self.mbundle, key, root, members, "reports",
            _MATRIX_BUNDLE_GENESIS,
        )

    # ------------------------------------------------------------- pbundle
    def proof_bundle(self, level: int, value: Any, field: str) -> _VNode:
        tag = {0: "b0", 1: "b1", 2: "b2"}[level]
        registry = (self.b0, self.b1, self.b2)[level]
        proof_parse = (
            self.evolution_proof, self.chain_proof, self.bundle_evolution_proof
        )[level]
        root, members = self._bundle_members(
            value, field, "proofs", "proof", proof_parse
        )
        key = _VKey(
            (tag, root, tuple((i, n.key, p, d) for i, n, p, d in members))
        )
        node = registry.get(key)
        if node is not None:
            return node
        return self._assemble_bundle(
            tag, registry, key, root, members, "proofs",
            _CHECKPOINT_BUNDLE_GENESIS
        )

    # -------------------------------------------------------------- diffs
    def _diff_changes(self, value, before_members, after_members, field,
                      side_parse, strict):
        if not isinstance(value, list):
            raise ValueError(f"{field} must be a list of change dicts")
        before_by_id = {m[0]: m for m in before_members}
        after_by_id = {m[0]: m for m in after_members}
        entries: list[tuple[str, str, _VNode | None, _VNode | None]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, change in enumerate(value):
            cf = f"{field}[{index}]"
            if not isinstance(change, dict) or set(change) != (
                _CHECKPOINT_BUNDLE_DIFF_CHANGE_KEYS
            ):
                raise ValueError(
                    f"{cf} must be a dict with exactly the keys id, kind, before, after"
                )
            member_id = _check_non_empty_str(change["id"], f"{cf}.id")
            if member_id in seen:
                raise ValueError(f"{field} contains a duplicate change id: {member_id!r}")
            if previous_id is not None and member_id <= previous_id:
                raise ValueError(
                    f"{field} must be ordered by id in ascending Unicode code "
                    "point order"
                )
            kind = change["kind"]
            if kind not in _CHECKPOINT_BUNDLE_DIFF_KINDS:
                raise ValueError(
                    f"{cf}.kind must be 'added', 'removed', or 'changed'"
                )
            bn = (
                None if change["before"] is None
                else side_parse(change["before"], f"{cf}.before")
            )
            an = (
                None if change["after"] is None
                else side_parse(change["after"], f"{cf}.after")
            )
            bm = before_by_id.get(member_id)
            am = after_by_id.get(member_id)
            if kind == "added":
                if bn is not None or an is None:
                    raise ValueError(
                        f"{cf} is 'added' but before/after do not match the contract"
                    )
                if bm is not None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not added between the two bundles"
                    )
                if an.semkey != am[1].semkey:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle member "
                        f"for id {member_id!r}"
                    )
            elif kind == "removed":
                if bn is None or an is not None:
                    raise ValueError(
                        f"{cf} is 'removed' but before/after do not match the contract"
                    )
                if bm is None or am is not None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not removed between the two bundles"
                    )
                if bn.semkey != bm[1].semkey:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle member "
                        f"for id {member_id!r}"
                    )
            else:
                if bn is None or an is None:
                    raise ValueError(
                        f"{cf} is 'changed' but before/after do not match the contract"
                    )
                if bm is None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} must exist in both bundles to be 'changed'"
                    )
                if bn.semkey != bm[1].semkey:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle member "
                        f"for id {member_id!r}"
                    )
                if an.semkey != am[1].semkey:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle member "
                        f"for id {member_id!r}"
                    )
            entries.append((member_id, kind, bn, an))
            seen.add(member_id)
            previous_id = member_id

        expected = set(before_by_id) ^ set(after_by_id)
        for member_id in sorted(set(before_by_id) & set(after_by_id)):
            if before_by_id[member_id][1].semkey != after_by_id[member_id][1].semkey:
                expected.add(member_id)
        if strict and seen != expected:
            raise ValueError(
                "changes must list exactly the added, removed, and changed "
                "members, with unchanged members omitted"
            )
        return entries, seen == expected

    def _assemble_diff(self, tag, registry, key, before_root, after_root,
                       digest, before, after, entries, five=None):
        if five is None:
            change_parts: list[str] = []
            for _id, kind, bn, an in entries:
                change_parts.append(
                    '{"id":' + _vjs(_id)
                    + ',"kind":' + _vjs(kind)
                    + ',"before":' + ("null" if bn is None else bn.json)
                    + ',"after":' + ("null" if an is None else an.json)
                    + "}"
                )
            five = (
                '{"before_root":' + _vjs(before_root)
                + ',"after_root":' + _vjs(after_root)
                + ',"before":' + before.json
                + ',"after":' + after.json
                + ',"changes":[' + ",".join(change_parts) + "]}"
            )
        node = _VNode()
        node.key = key
        node.root = before_root
        node.root_after = after_root
        node.digest = digest
        node.before_node = before
        node.after_node = after
        node.members = entries
        node.json = five[:-1] + ',"digest":' + _vjs(digest) + "}"
        node.dsem = {
            "before": before.sem,
            "after": after.sem,
            "changes": [
                {
                    "id": _id,
                    "kind": kind,
                    "before": None if bn is None else bn.sem,
                    "after": None if an is None else an.sem,
                }
                for _id, kind, bn, an in entries
            ],
        }
        node.dsemkey = (
            tag,
            before.semkey,
            after.semkey,
            tuple(
                (
                    _id,
                    kind,
                    None if bn is None else bn.semkey,
                    None if an is None else an.semkey,
                )
                for _id, kind, bn, an in entries
            ),
        )
        node.canonical = None
        registry[key] = node
        return node, five

    def _parse_diff(self, tag, registry, value, field, bundle_parse,
                    side_parse, strict):
        if not isinstance(value, dict) or set(value) != set(
            _CHECKPOINT_BUNDLE_DIFF_REPORT_KEYS
        ):
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "before_root, after_root, before, after, changes, digest"
            )
        before_root = _check_hex64(value["before_root"], f"{field}.before_root")
        after_root = _check_hex64(value["after_root"], f"{field}.after_root")
        digest = _check_hex64(value["digest"], f"{field}.digest")
        before = bundle_parse(value["before"], f"{field}.before")
        after = bundle_parse(value["after"], f"{field}.after")
        if before.root != before_root:
            raise ValueError(f"{field}.before_root must equal {field}.before.root")
        if after.root != after_root:
            raise ValueError(f"{field}.after_root must equal {field}.after.root")
        entries, complete = self._diff_changes(
            value["changes"], before.members, after.members,
            f"{field}.changes", side_parse, strict,
        )
        key = _VKey(
            (
                tag, before_root, after_root, digest, before.key, after.key,
                tuple(
                    (i, k, None if bn is None else bn.key,
                     None if an is None else an.key)
                    for i, k, bn, an in entries
                ),
            )
        )
        node = registry.get(key)
        if node is not None:
            return node
        node, five = self._assemble_diff(
            tag, registry, key, before_root, after_root, digest,
            before, after, entries,
        )
        recomputed = hashlib.sha256(five.encode("utf-8")).hexdigest()
        sides_ok = all(
            (bn is None or bn.truth) and (an is None or an.truth)
            for _i, _k, bn, an in entries
        )
        node.truth = bool(
            before.truth and after.truth and sides_ok and digest == recomputed
        )
        node.complete = complete
        return node

    def matrix_diff(self, value: Any, field: str) -> _VNode:
        return self._parse_diff(
            "mdiff", self.mdiff, value, field,
            lambda v, f: self.matrix_bundle(v, f),

        lambda v, f: self.matrix_bundle(v, f),
        lambda v, f: self.credential(v, f),
        strict=True,
    )

def proof_diff(self, level: int, value: Any, field: str) -> _VNode:
    tag = {0: "d0", 1: "d1", 2: "d2"}[level]
    registry = (self.d0, self.d1, self.d2)[level]
    bundle_parse = (
        (lambda v, f: self.proof_bundle(0, v, f)),
        (lambda v, f: self.proof_bundle(1, v, f)),
        (lambda v, f: self.proof_bundle(2, v, f)),
    )[level]
    side_parse = (
        self.evolution_proof, self.chain_proof, self.bundle_evolution_proof
    )[level]
    return self._parse_diff(
        tag, registry, value, field, bundle_parse, side_parse, strict=False
    )

def generate_diff(self, level, before: _VNode, after: _VNode) -> _VNode:
    """Canonical diff a generator produces from two canonical bundles."""
    if level == -1:
        tag, registry = "mdiff", self.mdiff
    else:
        tag = {0: "d0", 1: "d1", 2: "d2"}[level]
        registry = (self.d0, self.d1, self.d2)[level]
    before_by_id = {m[0]: m for m in before.members}
    after_by_id = {m[0]: m for m in after.members}
    entries: list[tuple[str, str, _VNode | None, _VNode | None]] = []
    for member_id in sorted(set(before_by_id) | set(after_by_id)):
        bm = before_by_id.get(member_id)
        am = after_by_id.get(member_id)
        if bm is not None and am is not None and bm[1].json == am[1].json:
            continue
        kind = "added" if bm is None else "removed" if am is None else "changed"
        entries.append(
            (member_id, kind, None if bm is None else bm[1],
             None if am is None else am[1])
        )
    change_keys = tuple(
        (i, k, None if bn is None else bn.key, None if an is None else an.key)
        for i, k, bn, an in entries
    )
    change_parts = [
        '{"id":' + _vjs(_id)
        + ',"kind":' + _vjs(kind)
        + ',"before":' + ("null" if bn is None else bn.json)
        + ',"after":' + ("null" if an is None else an.json)
        + "}"
        for _id, kind, bn, an in entries
    ]
    five = (
        '{"before_root":' + _vjs(before.root)
        + ',"after_root":' + _vjs(after.root)
        + ',"before":' + before.json
        + ',"after":' + after.json
        + ',"changes":[' + ",".join(change_parts) + "]}"
    )
    digest = hashlib.sha256(five.encode("utf-8")).hexdigest()
    full_key = _VKey(
        (tag, before.root, after.root, digest, before.key, after.key,
         change_keys)
    )
    existing = registry.get(full_key)
    if existing is not None:
        return existing
    node, _five = self._assemble_diff(
        tag, registry, full_key, before.root, after.root, digest,
        before, after, entries, five=five,
    )
    node.truth = True
    node.complete = True
    return node

# -------------------------------------------------------------- proofs
def _proof(self, tag, registry, value, field, genesis, bundle_parse,
           diff_level, diff_parse):
    if not isinstance(value, dict) or set(value) != {
        "start", "end", "anchor", "stages", "commitment"
    }:
        raise ValueError(
            f"{field} must be a dict with exactly the keys "
            "start, end, anchor, stages, commitment"
        )
    start = _check_time(value["start"], f"{field}.start")
    end = _check_time(value["end"], f"{field}.end")
    if start > end:
        raise ValueError(f"{field}.start must not be after {field}.end")
    anchor = _check_hex64(value["anchor"], f"{field}.anchor")
    commitment = _check_hex64(value["commitment"], f"{field}.commitment")
    raw_stages = value["stages"]
    if not isinstance(raw_stages, list) or not raw_stages:
        raise ValueError(f"{field}.stages must be a non-empty list")

    rows: list[tuple[str, _VNode, _VNode | None, str, str]] = []
    previous_at: str | None = None
    for index, stage in enumerate(raw_stages):
        sf = f"{field}.stages[{index}]"
        if not isinstance(stage, dict) or set(stage) != {
            "at", "bundle", "diff", "previous", "digest"
        }:
            raise ValueError(
                f"{sf} must be a dict with exactly the keys "
                "at, bundle, diff, previous, digest"
            )
        at = _check_time(stage["at"], f"{sf}.at")
        if previous_at is not None and at <= previous_at:
            raise ValueError(
                f"{sf}.at must be strictly greater than the preceding stage at"
            )
        prev = _check_hex64(stage["previous"], f"{sf}.previous")
        dig = _check_hex64(stage["digest"], f"{sf}.digest")
        bundle = bundle_parse(stage["bundle"], f"{sf}.bundle")
        diff: _VNode | None
        if index == 0 and prev == genesis:
            if stage["diff"] is not None:
                raise ValueError(f"{sf}.diff must be null at the genesis stage")
            diff = None
        else:
            diff = diff_parse(stage["diff"], f"{sf}.diff")
            if diff.root_after != bundle.root:
                raise ValueError(
                    f"{sf}.diff.after_root must equal this stage bundle root"
                )
            if diff.after_node.semkey != bundle.semkey:
                raise ValueError(
                    f"{sf}.diff.after must reproduce this stage bundle"
                )
            if index > 0:
                preceding_bundle = rows[-1][1]
                if diff.root != preceding_bundle.root:
                    raise ValueError(
                        f"{sf}.diff.before_root must equal the preceding "
                        "stage bundle root"
                    )
                if diff.before_node.semkey != preceding_bundle.semkey:
                    raise ValueError(
                        f"{sf}.diff.before must reproduce the preceding "
                        "stage bundle"
                    )
        rows.append((at, bundle, diff, prev, dig))
        previous_at = at

    key = _VKey(
        (
            tag, start, end, anchor, commitment,
            tuple(
                (at, b.key, None if d is None else d.key, p, h)
                for at, b, d, p, h in rows
            ),
        )
    )
    node = registry.get(key)
    if node is not None:
        return node

    truth = True
    running = anchor
    stage_parts: list[str] = []
    sem_stages: list[dict[str, Any]] = []
    semkey_stages: list[tuple[str, Any, Any]] = []
    for index, (at, bundle, diff, prev, dig) in enumerate(rows):
        if not bundle.truth:
            truth = False
        if diff is not None:
            if not diff.truth:
                truth = False
            if index == 0:
                generated = self.generate_diff(
                    diff_level, diff.before_node, diff.after_node
                )
            else:
                generated = self.generate_diff(
                    diff_level, rows[index - 1][1], bundle
                )
            if diff.json != generated.json:
                truth = False
        # Hash the stage payload incrementally from the cached child
        # bytes instead of concatenating a throwaway payload string.
        hasher = hashlib.sha256(running.encode("ascii"))
        hasher.update(b'{"at":')
        hasher.update(_vjs(at).encode("utf-8"))
        hasher.update(b',"bundle":')
        hasher.update(bundle.json.encode("utf-8"))
        hasher.update(b',"diff":')
        hasher.update(
            b"null" if diff is None else diff.json.encode("utf-8")
        )
        hasher.update(b"}")
        recomputed = hasher.hexdigest()
        if prev != running or dig != recomputed:
            truth = False
        running = recomputed
        stage_parts.append(
            '{"at":' + _vjs(at)
            + ',"bundle":' + bundle.json
            + ',"diff":' + ("null" if diff is None else diff.json)
            + ',"previous":' + _vjs(prev)
            + ',"digest":' + _vjs(dig) + "}"
        )
        sem_stages.append(
            {
                "at": at,
                "bundle": bundle.sem,
                "diff": None if diff is None else diff.dsem,
            }
        )
        semkey_stages.append(
            (
                at,
                bundle.semkey,
                None if diff is None else diff.dsemkey,
            )
        )
    if commitment != running:
        truth = False
    if not (start == rows[0][0] and end == rows[-1][0]):
        truth = False

    node = _VNode()
    node.key = key
    node.truth = truth
    node.members = rows
    node.stage_parts = stage_parts
    node.json = (
        '{"start":' + _vjs(start)
        + ',"end":' + _vjs(end)
        + ',"anchor":' + _vjs(anchor)
        + ',"stages":[' + ",".join(stage_parts)
        + '],"commitment":' + _vjs(commitment) + "}"
    )
    node.sem = {"start": start, "end": end, "stages": sem_stages}
    node.semkey = (tag, start, end, tuple(semkey_stages))
    node.canonical = None
    registry[key] = node
    return node

def evolution_proof(self, value, field):
    return self._proof(
        "p0", self.p0, value, field, _MATRIX_BUNDLE_EVOLUTION_GENESIS,
        lambda v, f: self.matrix_bundle(v, f),
        -1, lambda v, f: self.matrix_diff(v, f),
    )

def chain_proof(self, value, field):
    return self._proof(
        "p1", self.p1, value, field, _CHECKPOINT_CHAIN_GENESIS,
        lambda v, f: self.proof_bundle(0, v, f),
        0, lambda v, f: self.proof_diff(0, v, f),
    )

def bundle_evolution_proof(self, value, field):
    return self._proof(
        "p2", self.p2, value, field, _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS,
        lambda v, f: self.proof_bundle(1, v, f),
        1, lambda v, f: self.proof_diff(1, v, f),
    )

# ----------------------------------------------------- top-level diffs
def top_bundle(self, value: Any, field: str) -> _VNode:
    return self.proof_bundle(2, value, field)

def top_generate(self, before: _VNode, after: _VNode) -> _VNode:
    return self.generate_diff(2, before, after)

def top_parse_diff(self, value: Any, field: str) -> _VNode:
    return self.proof_diff(2, value, field)

# --------------------------------------------------------- generators
def build_chain(self, level: int, stages: Any, field: str = "stages") -> str:
    """Generate a ``root, stages`` chain report as canonical JSON text.

    Every stage bundle is parsed through the value engine (structural
    and embedded-proof checks) and must recompute as true; the adjacent
    diffs reuse the parsed bundle nodes directly, so no proof is
    normalized or recomputed twice. ``level`` is -1 for matrix bundle
    evolution, 0 for the checkpoint chain, and 1 for the chain window
    proof bundle evolution.
    """
    genesis, bundle_parse, diff_level = {
        -1: (
            _MATRIX_BUNDLE_EVOLUTION_GENESIS,
            self.matrix_bundle,
            -1,
        ),
        0: (
            _CHECKPOINT_CHAIN_GENESIS,
            lambda v, f: self.proof_bundle(0, v, f),
            0,
        ),
        1: (
            _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS,
            lambda v, f: self.proof_bundle(1, v, f),
            1,
        ),
    }[level]
    if not isinstance(stages, list) or not stages:
        raise ValueError(
            f"{field} must be a non-empty list of {{at, bundle}} dicts"
        )
    rows: list[tuple[str, _VNode]] = []
    previous_at: str | None = None
    for index, stage in enumerate(stages):
        sf = f"{field}[{index}]"
        if not isinstance(stage, dict) or set(stage) != {"at", "bundle"}:
            raise ValueError(
                f"{sf} must be a dict with exactly the keys at, bundle"
            )
        at = _check_time(stage["at"], f"{sf}.at")
        if previous_at is not None and at <= previous_at:
            raise ValueError(
                f"{sf}.at must be strictly greater than the preceding at"
            )
        node = bundle_parse(stage["bundle"], f"{sf}.bundle")
        if not node.truth:
            raise ValueError(
                f"{sf}.bundle root or hash chain does not verify"
            )
        rows.append((at, node))
        previous_at = at

    previous = genesis
    prior: _VNode | None = None
    parts: list[str] = []
    for at, node in rows:
        diff_node = (
            None if prior is None else self.generate_diff(diff_level, prior, node)
        )
        payload = (
            '{"at":' + _vjs(at)
            + ',"bundle":' + node.json
            + ',"diff":' + ("null" if diff_node is None else diff_node.json)
            + "}"
        )
        digest = hashlib.sha256(
            previous.encode("ascii") + payload.encode("utf-8")
        ).hexdigest()
        parts.append(
            payload[:-1]
            + ',"previous":' + _vjs(previous)
            + ',"digest":' + _vjs(digest) + "}"
        )
        previous = digest
        prior = node
    return '{"root":' + _vjs(previous) + ',"stages":[' + ",".join(parts) + "]}"

def _report_node(
    self, proof_parse: Any, genesis: str, report: Any, field: str
) -> _VNode:
    """Parse a ``root, stages`` chain report into a truth-checked node.

    The report is validated by the same proof-row machinery as a window
    proof covering every stage with the genesis anchor and the declared
    root as commitment: exact key sets, times, ordering, embedded
    bundles and adjacent diffs are structural checks (violations raise
    ``ValueError``), and any false proof, chain link, diff, stage
    digest, or root also raises ``ValueError`` here because generators
    never emit partial results.
    """
    if not isinstance(report, dict) or set(report) != {"root", "stages"}:
        raise ValueError(
            f"{field} must be a dict with exactly the keys root, stages"
        )
    root = _check_hex64(report["root"], f"{field}.root")
    raw_stages = report["stages"]
    if not isinstance(raw_stages, list) or not raw_stages:
        raise ValueError(f"{field}.stages must be a non-empty list")
    first, last = raw_stages[0], raw_stages[-1]
    synthetic = {
        "start": first.get("at") if isinstance(first, dict) else None,
        "end": last.get("at") if isinstance(last, dict) else None,
        "anchor": genesis,
        "stages": raw_stages,
        "commitment": root,
    }
    node = proof_parse(synthetic, field)
    if not node.truth:
        raise ValueError(
            f"{field} must be a fully verifiable chain report"
        )
    return node

def cut_window(
    self,
    level: int,
    report: Any,
    start: str,
    end: str,
    field: str = "report",
) -> str:
    """Cut a stage-window proof out of a fully verified chain report.

    The report is parsed and recomputed once; the returned canonical
    JSON text reuses the parsed stage bytes, so window stages are not
    normalized again. ``level`` is -1 for matrix bundle evolution
    reports, 0 for checkpoint chain reports, and 1 for chain window
    proof bundle evolution reports.
    """
    genesis, proof_parse = {
        -1: (_MATRIX_BUNDLE_EVOLUTION_GENESIS, self.evolution_proof),
        0: (_CHECKPOINT_CHAIN_GENESIS, self.chain_proof),
        1: (
            _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS,
            self.bundle_evolution_proof,
        ),
    }[level]
    node = self._report_node(proof_parse, genesis, report, field)
    rows = node.members
    ats = [row[0] for row in rows]
    if start not in ats:
        raise ValueError(
            "start must be the at of a stage that exists in report"
        )
    if end not in ats:
        raise ValueError(
            "end must be the at of a stage that exists in report"
        )
    first_index = ats.index(start)
    last_index = ats.index(end)
    anchor = genesis if first_index == 0 else rows[first_index - 1][4]
    return (
        '{"start":' + _vjs(start)
        + ',"end":' + _vjs(end)
        + ',"anchor":' + _vjs(anchor)
        + ',"stages":['
        + ",".join(node.stage_parts[first_index:last_index + 1])
        + '],"commitment":' + _vjs(rows[last_index][4]) + "}"
    )

def build_bundle(self, level: int, items: Any, field: str = "items") -> str:
    """Generate a ``root, proofs`` bundle as canonical JSON text.

    Every ``{id, proof}`` item's proof is parsed through the value
    engine and must recompute as true; equal-valued proofs collapse to
    one node, so a repeated proof is normalized and recomputed only
    once. ``level`` is 0 for evolution checkpoint proofs, 1 for chain
    window proofs, and 2 for bundle evolution window proofs.
    """
    proof_parse = (
        self.evolution_proof, self.chain_proof, self.bundle_evolution_proof
    )[level]
    if not isinstance(items, list) or not items:
        raise ValueError(
            f"{field} must be a non-empty list of {{id, proof}} dicts"
        )
    parsed: list[tuple[str, _VNode]] = []
    seen: set[str] = set()
    for index, item in enumerate(items):
        sf = f"{field}[{index}]"
        if not isinstance(item, dict) or set(item) != {"id", "proof"}:
            raise ValueError(
                f"{sf} must be a dict with exactly the keys id, proof"
            )
        item_id = _check_non_empty_str(item["id"], f"{sf}.id")
        if item_id in seen:
            raise ValueError(f"{field} contains a duplicate id: {item_id!r}")
        seen.add(item_id)
        node = proof_parse(item["proof"], f"{sf}.proof")
        if not node.truth:
            raise ValueError(f"{sf}.proof does not recompute as true")
        parsed.append((item_id, node))
    parsed.sort(key=lambda member: member[0])
    previous = _CHECKPOINT_BUNDLE_GENESIS
    parts: list[str] = []
    for item_id, node in parsed:
        payload = _v_member_payload("proof", item_id, node.json)
        digest = hashlib.sha256(
            previous.encode("ascii") + payload.encode("utf-8")
        ).hexdigest()
        parts.append(
            '{"id":' + _vjs(item_id)
            + ',"proof":' + node.json
            + ',"previous":' + _vjs(previous)
            + ',"digest":' + _vjs(digest) + "}"
        )
        previous = digest
    return '{"root":' + _vjs(previous) + ',"proofs":[' + ",".join(parts) + "]}"

