_VKEY_DICT = P._VKEY_DICT; _VKEY_LIST = P._VKEY_LIST; _VKEY_TUPLE = P._VKEY_TUPLE
_VKEY_BOOL = P._VKEY_BOOL; _VKEY_FLOAT = P._VKEY_FLOAT; _VKEY_OTHER = P._VKEY_OTHER
_vtype_key = P._vtype_key

def v_iter(value):
    # Iterative post-order walk; frames hold (kind, iterator, collected).
    if isinstance(value, str):
        return value
    if value is None:
        return None
    if isinstance(value, bool):
        return (_VKEY_BOOL, value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return (_VKEY_FLOAT, value)
    if isinstance(value, dict):
        kind = _VKEY_DICT
        iterator = iter(value.items())
        collected = []
        tagged = False
    elif isinstance(value, list):
        kind = _VKEY_LIST
        iterator = iter(value)
        collected = []
        tagged = None
    elif isinstance(value, tuple):
        kind = _VKEY_TUPLE
        iterator = iter(value)
        collected = []
        tagged = None
    else:
        return (_VKEY_OTHER, type(value).__qualname__, repr(value))
    stack = [(kind, iterator, collected, tagged)]
    result = None
    while stack:
        kind, iterator, collected, tagged = stack[-1]
        advanced = False
        for item in iterator:
            if kind is _VKEY_DICT:
                k, v = item
                if not tagged and not isinstance(k, str):
                    tagged = True
                key_repr = k
                val = v
            else:
                key_repr = None
                val = item
            # compute child key
            if isinstance(val, str):
                child = val
            elif val is None:
                child = None
            elif isinstance(val, bool):
                child = (_VKEY_BOOL, val)
            elif isinstance(val, int):
                child = val
            elif isinstance(val, float):
                child = (_VKEY_FLOAT, val)
            elif isinstance(val, (dict, list, tuple)):
                # descend
                if isinstance(val, dict):
                    ck = _VKEY_DICT; it = iter(val.items()); tg = False
                elif isinstance(val, list):
                    ck = _VKEY_LIST; it = iter(val); tg = None
                else:
                    ck = _VKEY_TUPLE; it = iter(val); tg = None
                stack.append((ck, it, [], tg))
                advanced = True
                break
            else:
                child = (_VKEY_OTHER, type(val).__qualname__, repr(val))
            if kind is _VKEY_DICT:
                collected.append((key_repr, child) if not tagged else (_vtype_key(key_repr), child))
            else:
                collected.append(child)
        else:
            stack.pop()
            if kind is _VKEY_DICT:
                if tagged:
                    # retag string keys
                    fixed = []
                    for k, c in collected:
                        # k may be raw str (appended before tagging discovered)
                        fixed.append((k if not isinstance(k, str) else ("s", k), c))
                    collected = fixed
                collected.sort()
            result = (kind, tuple(collected))
            if stack:
                pk, pi, pc, pt = stack[-1]
                if pk is _VKEY_DICT:
                    # need the pending key... PROBLEM: we lost the key of the child we descended into
                    pass
            continue
        if advanced:
            continue
    return result

# The iterative version above has a design problem (pending key on descend).
# Simpler: recursive but with local bindings.
def v_local(value, _str=str, _dict=dict, _list=list, _tuple=tuple, _bool=bool, _int=int, _float=float,
            _isinstance=isinstance, _D=_VKEY_DICT, _L=_VKEY_LIST, _T=_VKEY_TUPLE, _B=_VKEY_BOOL, _F=_VKEY_FLOAT, _O=_VKEY_OTHER, _vtk=_vtype_key):
    if _isinstance(value, _str):
        return value
    if _isinstance(value, _dict):
        items = []
        for key, item in value.items():
            if not _isinstance(key, _str):
                items = None
                break
            items.append((key, v_local(item)))
        if items is None:
            items = [(_vtk(k), v_local(v)) for k, v in value.items()]
        items.sort()
        return (_D, tuple(items))
    if _isinstance(value, _list):
        return (_L, tuple([v_local(i) for i in value]))
    if value is None:
        return None
    if _isinstance(value, _bool):
        return (_B, value)
    if _isinstance(value, _int):
        return value
    if _isinstance(value, _float):
        return (_F, value)
    if _isinstance(value, _tuple):
        return (_T, tuple([v_local(i) for i in value]))
    return (_O, type(value).__qualname__, repr(value))

cur = P._vvalue_key
def bench(fn, v, n=3000):
    fn(v)
    t0=time.perf_counter()
    for _ in range(n): fn(v)
    return (time.perf_counter()-t0)/n
print("current:", bench(cur, cred))
print("v_local:", bench(v_local, cred))
assert v_local(cred) == cur(cred)
